#include "fuzzer/FuzzedDataProvider.h"
#include <cstdint>
#include <fstream>
#include <iostream>
#include <string>
#include <unistd.h>
#include <vector>

#include "/src/tomlplusplus/toml.hpp"

// Target function: toml::v3::parse
// Target function: toml::v3::table::equal
// Target function: toml::v3::at_path
// Target function: toml::v3::yaml_formatter

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
  FuzzedDataProvider fdp(data, size);

  // Create a temporary file path
  std::string path = std::string("/tmp/") + _FUZZ_TARGET_NAME + ".tmp";

  // ANALYSIS: The function-level coverage report showed that
  // `toml::v3::impl::do_parse_file` and
  // `toml::v3::impl::impl_ex::parser::consume_rest_of_line` have 0% coverage.
  // This indicates that file parsing is not being fuzzed.
  // IMPLEMENTATION: The following code writes fuzzer data to a temporary file
  // and then parses it using `toml::parse_file`. This will exercise the file
  // parsing logic, including error handling for malformed lines.
  std::string toml_string = fdp.ConsumeRandomLengthString();
  std::ofstream out(path);
  out << toml_string;
  out.close();

  try {
    toml::table tbl = toml::parse_file(path);

    // ANALYSIS: The function `toml::v3::table::equal` has low branch coverage
    // (58.33%).
    // IMPLEMENTATION: The following code creates a second table and compares it
    // with the first one. The contents of the second table are generated by the
    // fuzzer, which will create different comparison scenarios and improve branch
    // coverage.
    toml::table tbl2;
    if (fdp.ConsumeBool()) {
      tbl2 = tbl;
    } else {
      std::string key = fdp.ConsumeRandomLengthString(16);
      std::string value = fdp.ConsumeRandomLengthString(16);
      tbl2.insert(key, value);
    }
    (void)(tbl == tbl2);

    // ANALYSIS: The function `toml::v3::at_path` has some uncovered branches.
    // IMPLEMENTATION: The following code generates a random path and uses it to
    // access elements in the parsed TOML table. This will help cover edge cases
    // in path resolution.
    std::string p = fdp.ConsumeRandomLengthString(16);
    try {
      (void)tbl.at_path(p);
    } catch (...) {
    }

    // ANALYSIS: The function `toml::v3::yaml_formatter::print_yaml_string` has
    // 0% coverage.
    // IMPLEMENTATION: The following code creates a `toml::yaml_formatter` and
    // uses it to print the parsed TOML table as a YAML string. This will
    // exercise the YAML formatting logic.
    if (fdp.ConsumeBool()) {
      std::cout << toml::yaml_formatter{tbl} << std::endl;
    }

  } catch (...) {
  }

  // Clean up the temporary file
  unlink(path.c_str());

  return 0;
}